%% 随机生成断路情况
n = 1000; % 蒙特卡罗生成的场景数量
Zij = zeros(n,122); % 断路情况
for i = 1:n
    for j = 1:122
        if rand<0.025
            Zij(i,j)=1;
        end
    end
end

f = zeros(n,1);
r_load = zeros(n,1);
V_bias = zeros(n,4);
R_load = zeros(n,123);
for i = 1:n
    [f(i),r_load(i),V_bias(i,:),R_load(i,:)] = IEEE123Random_scene(vals,Zij(i,:));
end

% 归一化的方法
Ees_cost = 105; % 电池配置价格 单位:万美元/10MWh 
w_ess = 0.003; % 储能成本权重-每年可能发生的 1-2 次 电网断电事故;储能预期使用年限：10 – 15 年

ob1 = 0.1*sum(f)/n;
X = 0.1*w_ess*Ees_cost*sum(vals);
objective = ob1+ X;

r_load = sum(r_load)/n;
V_bias = sum(V_bias)/n;
R_load = sum(R_load)/n;
V_bias = sum(V_bias)/4;
end




